/* The typings of @filen/sdk-rs's Node-API addon, generated by NAPI-RS (napi build) below this
 * header. They match what uniffi-bindgen-react-native generates for the same items, so code
 * written against the react-native build type-checks against this one.
 *
 * Load the addon in one Node environment per process: the Electron main process or a
 * utilityProcess, not renderers or worker_threads. The SDK's runtime and napi's are shared
 * by every environment in the process.
 *
 * A JS value of the wrong type for an argument (a number where a bigint belongs, a missing
 * required key, an asyncOpts_ whose signal is not an AbortSignal) throws napi's own error
 * synchronously, also from a method that returns a
 * Promise, where ubrn's async methods reject. So does a cache listener without an onMessages
 * method. Every SDK error of an async call rejects, as under ubrn.
 *
 * This header declares what napi cannot generate from Rust. */
/* eslint-disable */

/** An `Error` carrying the SDK object it was thrown for, as ubrn throws it. */
export interface UniffiThrownObject<T> extends Error {
	readonly inner: T
}

export type JsClientInterface = JsClient
export type UnauthJsClientInterface = UnauthJsClient
export type FilenSdkErrorInterface = FilenSdkError

/**
 * Receives every status-message batch the cache worker emits (see [`CacheStatusMessage`]).
 * Registered ONCE via [`JsClient::configure_cache`] and reused across worker restarts.
 */
export interface CacheStatusListener {
	onMessages(messages: Array<CacheStatusMessage>): void
}
